#!/usr/bin/env python3
"""
Blind discrimination rating + scoring (PLAN.md P2.2, docs/PREREGISTRATION.md).

Shows each item unlabelled and asks one binary question:
    "Was this written by a Kuwaiti person, or generated by a machine?"

Then applies the PRE-REGISTERED decision rule. The rater's own validity is
checked FIRST -- if real human anchors aren't identified reliably, the session
is void and no model number is reported.

Standalone:
  python probe/rate.py --set eval/raw/rating_set.jsonl --out eval/raw/probe_ratings.jsonl
  python probe/rate.py --score eval/raw/probe_ratings.jsonl        # re-score only
"""
import argparse, json, math, os, sys
from pathlib import Path

# Pre-registered. Do not change after data is seen.
H_MIN = 0.80          # rater validity floor
SHIP_MULT = 0.60      # M >= 0.60*H  -> prompting suffices
FULL_MULT = 0.30      # M <  0.30*H  -> full fine-tune justified
CARICATURE_MAX = 0.50 # C >= 0.50    -> rater cannot detect caricature


def wilson(k, n, z=1.96):
    if n == 0:
        return (0.0, 0.0)
    p = k / n
    d = 1 + z * z / n
    c = (p + z * z / (2 * n)) / d
    h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return (max(0.0, c - h), min(1.0, c + h))


def score(ratings):
    by = {}
    for r in ratings:
        by.setdefault(r["type"], []).append(r)

    def rate_human(t):
        rows = by.get(t, [])
        k = sum(1 for r in rows if r["verdict"] == "human")
        return k, len(rows), (k / len(rows) if rows else 0.0)

    kH, nH, H = rate_human("real")
    kM, nM, M = rate_human("model")
    kC, nC, C = rate_human("caricature")
    kF, nF, F = rate_human("floor")

    print("\n" + "=" * 62)
    print("PROBE RESULT")
    print("=" * 62)
    print(f"  H  real human judged human : {kH}/{nH} = {H:.1%}  CI {wilson(kH,nH)[0]:.1%}-{wilson(kH,nH)[1]:.1%}")
    print(f"  M  model  judged human     : {kM}/{nM} = {M:.1%}  CI {wilson(kM,nM)[0]:.1%}-{wilson(kM,nM)[1]:.1%}")
    print(f"  C  caricature judged human : {kC}/{nC} = {C:.1%}")
    print(f"  F  floor judged human      : {kF}/{nF} = {F:.1%}")

    print("\n--- rater validity (checked BEFORE any model claim) ---")
    if H < H_MIN:
        print(f"  *** SESSION VOID *** H={H:.1%} < {H_MIN:.0%}")
        print("  The rater did not reliably identify real Kuwaiti under these")
        print("  conditions, so no model number from this session is meaningful.")
        print("  Re-run with a different item pool. Do not report M.")
        return {"valid": False, "H": H, "M": None}
    print(f"  H = {H:.1%} >= {H_MIN:.0%}  -> session VALID")

    if C >= CARICATURE_MAX:
        print(f"\n  !! WARNING: C={C:.1%} >= {CARICATURE_MAX:.0%}")
        print("  The rater judged marker-stuffed caricature as human at a high rate.")
        print("  This does not void the session, but it means naturalness judgement")
        print("  cannot detect over-marking -- a finding in its own right.")

    ship, full = SHIP_MULT * H, FULL_MULT * H
    print(f"\n--- decision rule (pre-registered) ---")
    print(f"  ship-the-prompt line : M >= {ship:.1%}")
    print(f"  full-fine-tune line  : M <  {full:.1%}")
    print(f"  observed M           : {M:.1%}")

    if M >= ship:
        verdict = "PROMPTING SUFFICES"
        action = "Stop. Ship the prompted demo. Phase 1 and 2 are cancelled."
    elif M >= full:
        verdict = "PARTIAL"
        action = "Fine-tune scoped to the specific failure modes listed, not a general run."
    else:
        verdict = "PROMPTING INSUFFICIENT"
        action = "Proceed to Phase 1 as planned, with justification on record."
    print(f"\n  VERDICT: {verdict}\n  ACTION : {action}")
    print("=" * 62)
    return {"valid": True, "H": H, "M": M, "C": C, "F": F,
            "verdict": verdict, "ship_line": ship, "full_line": full}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--set", dest="set_path")
    ap.add_argument("--out", default="eval/raw/probe_ratings.jsonl")
    ap.add_argument("--score", dest="score_path", help="re-score an existing ratings file")
    args = ap.parse_args()

    if args.score_path:
        rows = [json.loads(l) for l in open(args.score_path, encoding="utf-8")]
        score([r for r in rows if r.get("kind") == "rating"])
        return

    if not args.set_path:
        sys.exit("need --set or --score")

    rows = [json.loads(l) for l in open(args.set_path, encoding="utf-8")]
    meta = rows[0]
    items = [r for r in rows if "item_id" in r]

    done = {}
    if os.path.exists(args.out):
        for l in open(args.out, encoding="utf-8"):
            r = json.loads(l)
            if r.get("kind") == "rating":
                done[r["item_id"]] = r
        if done:
            print(f"resuming: {len(done)}/{len(items)} already rated")

    print("\n" + "=" * 62)
    print("BLIND RATING")
    print("=" * 62)
    print("For each text answer:  h = written by a Kuwaiti person")
    print("                       m = generated by a machine")
    print("                       s = skip   q = save and quit")
    print("You are NOT told which is which. Answer on instinct; don't deliberate.")
    print("=" * 62)

    f = open(args.out, "a", encoding="utf-8")
    if not done:
        f.write(json.dumps({"kind": "rating_meta", **{k: v for k, v in meta.items()
                                                      if k != "kind"}}, ensure_ascii=False) + "\n")
    try:
        for i, it in enumerate(items, 1):
            if it["item_id"] in done:
                continue
            print(f"\n[{i}/{len(items)}]")
            print("-" * 62)
            print(it["text"])
            print("-" * 62)
            while True:
                a = input("  h / m / s / q > ").strip().lower()
                if a in ("h", "m", "s", "q"):
                    break
            if a == "q":
                print("saved.")
                break
            if a == "s":
                continue
            f.write(json.dumps({"kind": "rating", "item_id": it["item_id"],
                                "type": it["type"], "hash": it["hash"],
                                "verdict": "human" if a == "h" else "machine"},
                               ensure_ascii=False) + "\n")
            f.flush()
    finally:
        f.close()

    rows = [json.loads(l) for l in open(args.out, encoding="utf-8")]
    score([r for r in rows if r.get("kind") == "rating"])


if __name__ == "__main__":
    main()
